<section class="admin-page"><div class="container"><div class="admin-heading"><div><a class="back-link" href="<?= e(url('admin')) ?>">← Dashboard</a><h1><?= e($title) ?></h1><p><?= count($rows) ?> inzending(en)</p></div><a class="button primary" href="<?= e(url('admin/export/'.$type)) ?>">Exporteer CSV ↓</a></div>
<div class="table-wrap"><table><thead><tr><?php foreach($columns as $label): ?><th><?= e($label) ?></th><?php endforeach; ?><?php if($type==='sponsors'): ?><th>Beheer</th><?php endif; ?></tr></thead><tbody>
<?php if(!$rows): ?><tr><td colspan="<?= count($columns)+1 ?>">Nog geen inzendingen.</td></tr><?php endif; ?>
<?php foreach($rows as $row): ?><tr><?php foreach($columns as $key=>$label): ?><td data-label="<?= e($label) ?>"><?= nl2br(e((string)($row[$key] ?? ''))) ?></td><?php endforeach; ?><?php if($type==='sponsors'): ?><td data-label="Beheer"><details><summary>Aanpassen</summary><form method="post" action="<?= e(url('admin/sponsors/'.$row['id'])) ?>"><?= csrf_field() ?><label>Status<select name="status"><?php foreach(['Nieuw','Benaderd','Geïnteresseerd','Bevestigd','Afgehaakt'] as $status): ?><option<?= $row['status']===$status?' selected':'' ?>><?= e($status) ?></option><?php endforeach; ?></select></label><label>Notities<textarea name="admin_notes" rows="3"><?= e($row['admin_notes']) ?></textarea></label><button class="button small primary">Opslaan</button></form></details></td><?php endif; ?></tr><?php endforeach; ?>
</tbody></table></div></div></section>
